{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Ketoprofen, a benzoyl arylpropionic acid NSAID sharing the benzoyl ketone and carboxylic acid pharmacophore with the query, has absolute oral bioavailability exceeding 90% versus i.v. in humans, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiaprofenic acid, another benzoyl carboxylic acid NSAID, is almost completely absorbed with oral bioavailability of about 90–100% in humans, supporting high F for the structurally related acidic query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acidic benzoyl-pyrrole carboxylic acid (ketorolac-like NSAID). The most transferable evidence comes from ketoprofen and tiaprofenic acid, both benzoyl carboxylic acids with high absolute oral bioavailability in humans (84–100%). Low-bioavailability evidence in the set comes from basic, extensively metabolized drugs such as indoramin, fentanyl, and cocaine, which share little structural or physicochemical similarity with the acidic query. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule is present in the evidence set.",
    "The closest analogues have low Morgan similarity scores (~0.27), so transferability is limited.",
    "No human absolute oral bioavailability study for ketorolac itself is included among the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

